async function listCloudChildPhotos(profileId){const folder=cloudChildPhotoFolder(profileId);if(!folder||!supabaseClient)return[];try{const {data,error}=await supabaseClient.storage.from(CHILD_PHOTO_BUCKET).list(folder,{limit:20,sortBy:{column:'updated_at',order:'desc'}});if(error)return[];return(data||[]).filter(o=>/^reference(?:-\d+)?\.jpg$/i.test(o.name||'')).sort((a,b)=>{const av=Number((a.name||'').match(/reference-(\d+)\.jpg/i)?.[1]||0),bv=Number((b.name||'').match(/reference-(\d+)\.jpg/i)?.[1]||0);if(av!==bv)return bv-av;return String(b.updated_at||b.created_at||'').localeCompare(String(a.updated_at||a.created_at||''))})}catch{return[]}}
async function downloadCloudChildPhoto(profileId,objectName){const folder=cloudChildPhotoFolder(profileId);const path=folder&&objectName?`${folder}/${objectName}`:null;if(!path||!supabaseClient)return null;try{const {data,error}=await supabaseClient.storage.from(CHILD_PHOTO_BUCKET).download(path);if(error||!data)return null;return await blobToDataUrl(data)}catch{return null}}
async function uploadCloudChildPhoto(profileId,image){const folder=cloudChildPhotoFolder(profileId),path=cloudChildPhotoPath(profileId);if(!folder||!path||!image||!supabaseClient)return false;try{const {error}=await supabaseClient.storage.from(CHILD_PHOTO_BUCKET).upload(path,dataUrlToBlob(image),{contentType:'image/jpeg',upsert:false,cacheControl:'3600'});if(error){console.warn('Child photo cloud upload failed:',error.message);return false}const objectName=path.slice(folder.length+1);await childPhotoPut(currentPhotoKey(profileId),image,{cloudObject:objectName});cloudPhotoResolved.set(profileId,{image,cloudObject:objectName});const older=(await listCloudChildPhotos(profileId)).filter(o=>o.name!==objectName).map(o=>`${folder}/${o.name}`);if(older.length){try{await supabaseClient.storage.from(CHILD_PHOTO_BUCKET).remove(older)}catch{}}return true}catch(e){console.warn('Child photo cloud upload failed:',e?.message||e);return false}}
async function deleteCloudChildPhoto(profileId){const folder=cloudChildPhotoFolder(profileId);if(!folder||!supabaseClient)return;try{const objects=await listCloudChildPhotos(profileId),paths=objects.map(o=>`${folder}/${o.name}`);if(paths.length){const {error}=await supabaseClient.storage.from(CHILD_PHOTO_BUCKET).remove(paths);if(error)console.warn('Child photo cloud removal failed:',error.message)}}catch{}cloudPhotoResolved.delete(profileId)}
async function localChildPhotoRecordForProfile(profileId){const exactKey=currentPhotoKey(profileId),exact=await childPhotoRecord(exactKey);if(exact?.image)return exact;const db=await openImageDb();if(!db||!profileId)return null;const suffix=`:${profileId}`;const found=await new Promise(resolve=>{try{const tx=db.transaction(CHILD_PHOTO_STORE,'readonly'),req=tx.objectStore(CHILD_PHOTO_STORE).getAll();req.onsuccess=()=>{const rows=(req.result||[]).filter(r=>String(r.key||'').endsWith(suffix)&&r.image).sort((a,b)=>(b.at||0)-(a.at||0));resolve(rows[0]||null)};req.onerror=()=>resolve(null)}catch{resolve(null)}});if(found)await childPhotoPut(exactKey,found.image,{cloudObject:found.cloudObject||null});return found}
async function localChildPhotoForProfile(profileId){return(await localChildPhotoRecordForProfile(profileId))?.image||null}
async function childPhotoGetForProfile(profileId){
 if(!profileId)return childPhotoGet(currentPhotoKey());
 const local=await localChildPhotoRecordForProfile(profileId);
 if(!currentUser){if(local?.image)cloudPhotoResolved.set(profileId,{image:local.image,cloudObject:local.cloudObject||null});return local?.image||null}
 // V172: Supabase is authoritative. List lightweight object metadata every time the
 // profile is resolved; a new versioned object name means another device replaced
 // the photo, so this device refreshes its IndexedDB cache. Versioned object names
 // also avoid stale CDN responses from overwriting a newly selected profile photo.
 const objects=await listCloudChildPhotos(profileId),latest=objects[0]||null;
 if(latest){
  if(local?.image&&local.cloudObject===latest.name){cloudPhotoResolved.set(profileId,{image:local.image,cloudObject:latest.name});return local.image}
  const cloud=await downloadCloudChildPhoto(profileId,latest.name);
  if(cloud){await childPhotoPut(currentPhotoKey(profileId),cloud,{cloudObject:latest.name});cloudPhotoResolved.set(profileId,{image:cloud,cloudObject:latest.name});return cloud}
  return local?.image||null
 }
 if(local?.image){const uploaded=await uploadCloudChildPhoto(profileId,local.image);return uploaded?(cloudPhotoResolved.get(profileId)?.image||local.image):local.image}
 cloudPhotoResolved.set(profileId,{image:null,cloudObject:null});return null
}
async function childPhotoPut(key,image,meta={}){const db=await openImageDb();if(!db||!image)return;try{await new Promise(resolve=>{const tx=db.transaction(CHILD_PHOTO_STORE,'readwrite');tx.objectStore(CHILD_PHOTO_STORE).put({key,image,at:Date.now(),cloudObject:meta.cloudObject||null});tx.oncomplete=()=>resolve();tx.onerror=()=>resolve()})}catch{}}
async function childPhotoDelete(key){const db=await openImageDb();if(!db)return;try{await new Promise(resolve=>{const tx=db.transaction(CHILD_PHOTO_STORE,'readwrite');tx.objectStore(CHILD_PHOTO_STORE).delete(key);tx.oncomplete=()=>resolve();tx.onerror=()=>resolve()})}catch{}}
function currentPhotoKey(profileId=activeProfileId){return `child-photo:${currentUser?.id||'guest'}:${profileId||'draft'}`}
function renderChildPhoto(){const preview=$('childPhotoPreview'),remove=$('removeChildPhoto'),toggle=$('useChildPhoto');if(!preview)return;if(currentChildPhoto){preview.innerHTML=`<img src="${currentChildPhoto}" alt="Child photo preview">`;remove?.classList.remove('hidden');if(toggle)toggle.disabled=false}else{preview.innerHTML=`<span>☾</span><small>${escapeHtml(t().noPhoto)}</small><small class="photo-drop-hint">${escapeHtml(t().dropPhoto||'Drop photo here')}</small>`;remove?.classList.add('hidden');if(toggle){toggle.checked=true;toggle.disabled=true}}}
function renderChildPhotoLoading(){const preview=$('childPhotoPreview'),remove=$('removeChildPhoto'),toggle=$('useChildPhoto');if(!preview)return;preview.innerHTML=`<span class="child-photo-loading-spinner" aria-hidden="true"></span><small>${escapeHtml(t().photoLoading||'Loading photo…')}</small>`;remove?.classList.add('hidden');if(toggle)toggle.disabled=true}
async function loadCurrentChildPhoto(){if(activeProfileId)renderChildPhotoLoading();currentChildPhoto=activeProfileId?await childPhotoGetForProfile(activeProfileId):await childPhotoGet(currentPhotoKey());renderChildPhoto()}
function resizeChildPhoto(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read that photo.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('That image format could not be opened.'));img.onload=()=>{const max=768,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);resolve(canvas.toDataURL('image/jpeg',0.84))};img.src=reader.result};reader.readAsDataURL(file)})}
async function chooseChildPhoto(file){if(!file)return;const status=$('photoStatus');try{if(!/^image\/(jpeg|png|webp)$/i.test(file.type))throw new Error('Please choose a JPG, PNG or WebP photo.');if(status)status.textContent='Preparing photo…';const image=await resizeChildPhoto(file);currentChildPhoto=image;await childPhotoPut(currentPhotoKey(),image);if(activeProfileId)await uploadCloudChildPhoto(activeProfileId,image);if($('useChildPhoto'))$('useChildPhoto').checked=true;renderChildPhoto();if(status)status.textContent='Photo ready for illustrations.'}catch(e){if(status)status.innerHTML=`<span class="error">${escapeHtml(e.message||e)}</span>`}}
async function removeChildPhoto(){await childPhotoDelete(currentPhotoKey());if(activeProfileId)await deleteCloudChildPhoto(activeProfileId);currentChildPhoto=null;renderChildPhoto();if($('photoStatus'))$('photoStatus').textContent='Photo removed.'}
async function pruneImageCache(){const db=await openImageDb();if(!db)return;try{const rows=await new Promise(resolve=>{const tx=db.transaction(IMAGE_STORE,'readonly'),req=tx.objectStore(IMAGE_STORE).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>resolve([])});if(rows.length<=IMAGE_CACHE_LIMIT)return;rows.sort((a,b)=>(b.at||0)-(a.at||0));const remove=rows.slice(IMAGE_CACHE_LIMIT);await new Promise(resolve=>{const tx=db.transaction(IMAGE_STORE,'readwrite'),store=tx.objectStore(IMAGE_STORE);remove.forEach(r=>store.delete(r.key));tx.oncomplete=()=>resolve();tx.onerror=()=>resolve()})}catch{}}
function stableHash(value){let h=2166136261>>>0;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
function makeStoryCacheId(s,child){return stableHash(JSON.stringify({t:s.title||'',o:s.opening||'',b:s.character_bible||'',p:(s.pages||[]).map(x=>[x.text||'',x.illustration_prompt||'']),c:s.closing||'',n:child?.name||'',a:child?.age||'',g:child?.gender||'',r:child?.referenceImages?stableHash(JSON.stringify(child.referenceImages.map(x=>[x.name,x.role,x.gender||'',(x.image||'').slice(-400)]))):child?.referencePhoto?stableHash(child.referencePhoto.slice(-1200)):'none'}))}
async function requestIllustration(key,prompt,style,force=false,referenceImage=null,requiredStoryImage=false,storyImageIndex=null,continuityImage=null,developerCorrection=false,correctionMask=null){
 if(!force&&illustrationCache.has(key))return illustrationCache.get(key);
 if(!force){const stored=await persistentImageGet(key);if(stored){illustrationCache.set(key,stored);return stored}}
 if(!force&&illustrationInflight.has(key))return illustrationInflight.get(key);
 const continuityThumb=continuityImage?await illustrationContinuityReference(continuityImage):null;
 const task=(async()=>{let attempts=0,authRefreshed=false;while(attempts<3){attempts++;let accessToken=await currentAccessToken();if(!accessToken){authRefreshed=true;accessToken=await refreshAccessToken()}if(!accessToken)throw new Error('Your Moonbeam session has expired. Please sign in again.');const generationRunId=currentBook?.generationRunId||null;if(!generationRunId)throw new Error('This saved story predates the secure illustration allowance.');const response=await fetch('/api/illustrate',{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${accessToken}`},body:JSON.stringify({prompt,style,referenceImage:Array.isArray(referenceImage)?null:(referenceImage||null),referenceImages:Array.isArray(referenceImage)?referenceImage:null,continuityImage:continuityThumb||null,generationRunId,requiredStoryImage:requiredStoryImage===true,storyImageIndex:Number.isInteger(storyImageIndex)?storyImageIndex:null,developerCorrection:developerCorrection===true,correctionMask:developerCorrection&&correctionMask?correctionMask:null})});const raw=await response.text();let data=null;try{data=JSON.parse(raw)}catch{}if(response.ok&&data?.image){
   if(referenceImage && data.usedReferencePhoto!==true) throw new Error('One or more Cast photo references were not accepted by the illustration service.');
   illustrationCache.set(key,data.image);persistentImagePut(key,data.image);return data.image}if(response.status===401&&!authRefreshed&&attempts<3){authRefreshed=true;const refreshedToken=await refreshAccessToken();if(refreshedToken)continue;throw new Error('Your Moonbeam session has expired. Please sign in again.')}if((response.status===429||response.status===503)&&attempts<3){const wait=Math.min(12000,1800*Math.pow(2,attempts-1));await new Promise(r=>setTimeout(r,wait));continue}throw new Error(data?.error||`Illustration service failed (${response.status})`)}throw new Error('Illustration service is busy. Please try again.')})();
 illustrationInflight.set(key,task);try{return await task}finally{illustrationInflight.delete(key)}
}
