function coverT(){return coverLocales[language]||coverLocales['en-GB']}
function coverHeroNames(book=currentBook){const castNames=(book?.child?.cast||[]).filter(m=>m?.role==='hero').map(m=>String(m.name||'').trim()).filter(Boolean).slice(0,2);const savedNames=Array.isArray(book?.savedAssets?.heroNames)?book.savedAssets.heroNames.map(n=>String(n||'').trim()).filter(Boolean).slice(0,2):[];const names=castNames.length?castNames:savedNames;if(!names.length&&book?.child?.name)names.push(String(book.child.name).trim());return [...new Set(names)]}
function coverHeroList(names,locale=language){if(names.length<2)return names[0]||'';const conjunction={'en-GB':'and','en-US':'and','es-ES':'y','es-419':'y','fr-FR':'et','de-DE':'und','it-IT':'e','pt-BR':'e','pl-PL':'i'}[locale]||'and';return `${names[0]} ${conjunction} ${names[1]}`}
function developerChildCoverCredit(book=currentBook){if(!instagramDeveloperAccess)return '';const names=coverHeroNames(book);if(names.length!==1)return '';const name=String(names[0]||'').trim().toLowerCase();if(name==='sam')return 'By Sam Alderwick';if(name==='emily')return 'By Emily Alderwick';if(name==='isla')return 'By Isla Templeton';return ''}
function coverSubtitle(book=currentBook){if(book?.child?.seriesVolumeStory)return '';return String(book?.coverByline||book?.dedication||'').trim()||developerChildCoverCredit(book)||coverT().forChild(coverHeroList(coverHeroNames(book),language))}
function savedStoryVolumeLink25210(storyId){return developerSeriesLibrary.links.find(l=>l.story_id===storyId)||null}
function seriesVolumeCoverCopy25210(book=currentBook){if(!book?.child?.seriesVolumeStory)return `<div class="cover-copy"><div class="cover-kicker">${escapeHtml(coverT().kicker)}</div><h2>${escapeHtml(book?.title||'')}</h2><p id="coverSubtitle">${escapeHtml(coverSubtitle(book))}</p></div>`;if(book?.isSaved&&book?.savedAssets?.coverFlattened)return '';return `<div class="cover-copy series-volume-cover-copy"><h2>${escapeHtml(book?.title||'')}</h2></div>`}
function refreshCoverSubtitle(){const el=$('coverSubtitle');if(el&&currentBook)el.textContent=coverSubtitle(currentBook)}
function refreshCoverTextOverlay(book=currentBook){
 if(!book)return;
 const titleEl=document.querySelector('#coverView .cover-copy h2');if(titleEl)titleEl.textContent=book.title||t().title;
 refreshCoverSubtitle();
}
function reelHeroCastEntries(book=currentBook){const source=(book?.child?.cast?.length?book.child.cast:(Array.isArray(book?.savedAssets?.reelCast)?book.savedAssets.reelCast:[]))||[];const heroes=source.filter(m=>m?.role==='hero'&&m?.kind==='child').slice(0,2).map(m=>({id:m.id||null,name:String(m.name||'').trim(),gender:m.gender==='female'?'female':m.gender==='male'?'male':null,kind:'child',role:'hero',referencePhoto:m.referencePhoto||null})).filter(m=>m.name||m.id||m.referencePhoto);if(heroes.length)return heroes;const fallbackName=String(book?.child?.name||'').trim();if(!fallbackName)return [];return [{id:book?.child?.profileId||null,name:fallbackName,gender:book?.child?.gender==='female'?'female':book?.child?.gender==='male'?'male':null,kind:'child',role:'hero',referencePhoto:book?.child?.referencePhoto||null}]}
async function instagramReelHeroes(book=currentBook){const heroes=reelHeroCastEntries(book),resolved=[];for(const hero of heroes){let photo=hero.referencePhoto||null;if(!photo&&hero.id)try{photo=await childPhotoGetForProfile(hero.id)||null}catch{}if(photo)resolved.push({...hero,referencePhoto:photo})}if(resolved.length)return resolved;const fallback=String(book?.child?.referencePhoto||'').trim();if(fallback){const name=String(book?.child?.name||'').trim()||'Child';resolved.push({id:book?.child?.profileId||null,name,gender:book?.child?.gender==='female'?'female':book?.child?.gender==='male'?'male':null,kind:'child',role:'hero',referencePhoto:fallback})}return resolved.slice(0,2)}
function instagramReelIntroCopy(heroes){const names=heroes.map(h=>String(h?.name||'').trim()).filter(Boolean).slice(0,2);const subject=coverHeroList(names.length?names:['your child']);if(names.length>1)return {heading:`Meet ${subject}`,lines:[`${subject} love stories`,`They love them even more when they’re in them`,`Here’s a story Moonbeam made for ${subject}`]};const hero=heroes[0]||{},name=names[0]||'your child';let middle=`They love them even more when they’re in them`;if(hero.gender==='female')middle='She loves them even more when she’s in them';else if(hero.gender==='male')middle='He loves them even more when he’s in them';return {heading:`Meet ${name}`,lines:[`${name} loves stories`,middle,`Here’s a story Moonbeam made for ${name}`]}}

