function applyLandingLocale(){const x=LANDING_LOCALES[language]||LANDING_LOCALES['en-GB'];const text=(id,v)=>{const e=$(id);if(e)e.textContent=v};const html=(id,v)=>{const e=$(id);if(e)e.innerHTML=v};text('landingSignIn',x.signIn);text('landingKicker',x.kicker);html('landingHeadline',x.headline);text('landingCopy',x.copy);text('landingStart',x.start);text('landingFree',x.free);const demo=document.querySelector('.hero-demo'),img=document.querySelector('.hero-demo img');if(demo)demo.setAttribute('aria-label',x.demo);if(img)img.alt=x.demoAlt;text('homeHowKicker',x.howK);text('homeHowTitle',x.howT);text('homeStep1Title',x.s1t);text('homeStep1Copy',x.s1c);text('homeStep2Title',x.s2t);text('homeStep2Copy',x.s2c);text('homeStep3Title',x.s3t);text('homeStep3Copy',x.s3c);text('homeShowKicker',x.showK);text('homeShowTitle',x.showT);text('homeShowCopy',x.showC);const showImg=$('homeShowImage');if(showImg)showImg.alt=x.showAlt;text('homeTrustKicker',x.trustK);text('homeTrustTitle',x.trustT);text('homeTrustLead',x.trustL);text('homeTrust1Title',x.t1t);text('homeTrust1Copy',x.t1c);text('homeTrust2Title',x.t2t);text('homeTrust2Copy',x.t2c);text('homeTrust3Title',x.t3t);text('homeTrust3Copy',x.t3c);text('homePrivacyLink',x.privacy);text('homeFinalKicker',x.finalK);text('homeFinalTitle',x.finalT);text('homeFinalCopy',x.finalC);text('landingStartBottom',x.start);text('homeFinalFree',x.free);const landing=$('landingLanguage');if(landing)landing.value=language;}
function applyLocale(){
 const x=t(); document.documentElement.lang=language; document.title=x.title;
 $('tagline').textContent=x.tagline; if($('languageLabel'))$('languageLabel').textContent=x.language;
 $('childTitle').textContent=x.childTitle; setText('.setup-child-page .setup-page-heading .muted',x.childIntro); setText('.child-photo-column>h3',x.photoHeading); $('nameLabel').textContent=x.name; $('name').placeholder=x.namePh; $('ageLabel').textContent=x.age;
 $('interestsLabel').textContent=x.interests; $('interests').placeholder=x.interestsPh; $('dislikesLabel').textContent=x.dislikes; $('dislikes').placeholder=x.dislikesPh;
 $('storyPrefs').textContent=x.storyPrefs; $('toneLabel').textContent=x.tone; $('valuesTitle').textContent=x.values;
 $('generate').textContent=x.generate; if($('savedTitle'))$('savedTitle').textContent=x.saved;
 const tones=[['cosy and funny',x.cosy],['magical',x.magical],['adventurous',x.adventurous],['calm and dreamy',x.calm]]; const old=$('tone').value||'cosy and funny'; $('tone').innerHTML=tones.map(([v,l])=>`<option value="${v}" ${v===old?'selected':''}>${l}</option>`).join('');
 renderDesktopStoryPanel(); renderValues(); renderLibrary(); applyInterfaceLocale(); renderProfileSelect(); applyLandingLocale();
}
