function resetInstagramDeveloperAccess(user=currentUser){
 instagramDeveloperAccess=false;
 instagramDeveloperAccessState=user?'unknown':'anonymous';
 instagramDeveloperAccessPromise=null;
 instagramDeveloperAccessUserId=user?.id||null;
 $('instagramDemoChildBox')?.classList.add('hidden');
 $('developerStoryLengthBox')?.classList.add('hidden');
 mountFictionStudioEntry25229();
}
function mountInstagramDemoChildButton(){
 const box=$('instagramDemoChildBox');if(!box)return;
 // Developer controls are deliberately self-healing so a stale/mismatched HTML shell cannot reduce the generator to a one-click random child.
 if(!$('instagramDemoChildGender')||!$('instagramDemoChildAge')){
  const button=$('instagramDemoChildButton');
  const options=document.createElement('div');options.className='instagram-demo-child-options';
  options.innerHTML='<label><span>Gender</span><select id="instagramDemoChildGender"><option value="random" selected>Random</option><option value="male">Boy</option><option value="female">Girl</option></select></label><label><span>Age</span><select id="instagramDemoChildAge"><option value="random" selected>Random</option>'+Array.from({length:10},(_,i)=>`<option value="${i+3}">${i+3}</option>`).join('')+'</select></label>';
  if(button)box.insertBefore(options,button);else box.appendChild(options);
 }
 box.classList.toggle('hidden',!instagramDeveloperAccess);
 $('developerStoryLengthBox')?.classList.toggle('hidden',!instagramDeveloperAccess);
 $('developerWorkshopStart')?.classList.toggle('hidden',!instagramDeveloperAccess);
 mountFictionStudioEntry25229();
}
function mountInstagramEndButton(){
 if(!instagramDeveloperAccess||!currentBook||currentBook.isShared||currentBook.currentPage!==currentBook.pages.length+2)return;
 const actions=document.querySelector('.end-actions');if(!actions)return;
 if(!$('endInstagramPost')){const button=document.createElement('button');button.className='secondary end-instagram-post';button.id='endInstagramPost';button.type='button';button.textContent='Post carousel to Instagram';button.onclick=postCurrentStoryToInstagram;actions.appendChild(button)}
 if(!$('endInstagramReel')){const button=document.createElement('button');button.className='secondary end-instagram-post end-instagram-reel';button.id='endInstagramReel';button.type='button';button.textContent='Post reel to Instagram';button.onclick=postCurrentStoryReelToInstagram;actions.appendChild(button)}
}
async function checkInstagramDeveloperAccess({force=false}={}){
 const userId=currentUser?.id||null;
 if(!userId||!supabaseClient){resetInstagramDeveloperAccess(null);return false}
 if(instagramDeveloperAccessUserId!==userId)resetInstagramDeveloperAccess(currentUser);
 if(instagramDeveloperAccessState==='granted'){mountInstagramEndButton();mountInstagramDemoChildButton();loadDeveloperSeriesLibrary();return true}
 if(instagramDeveloperAccessState==='denied'&&!force)return false;
 if(instagramDeveloperAccessPromise)return instagramDeveloperAccessPromise;
 instagramDeveloperAccessState='checking';
 const request=(async()=>{
  try{
   const token=await currentAccessToken();if(!token){instagramDeveloperAccessState='unknown';return false}
   const r=await fetch('/api/resend-inbound?action=instagram-access',{cache:'no-store',credentials:'same-origin',headers:{Authorization:`Bearer ${token}`,'Cache-Control':'no-cache'}});
   if(currentUser?.id!==userId)return false;
   instagramDeveloperAccess=r.ok;
   instagramDeveloperAccessState=r.ok?'granted':((r.status===401||r.status===403)?'denied':'unknown');
   if(r.ok){mountInstagramEndButton();mountInstagramDemoChildButton();refreshCoverSubtitle();await loadDeveloperSeriesLibrary()}
   return r.ok;
  }catch(error){
   if(currentUser?.id===userId){instagramDeveloperAccess=false;instagramDeveloperAccessState='unknown'}
   console.warn('Instagram developer access check',error);return false;
  }finally{if(instagramDeveloperAccessPromise===request)instagramDeveloperAccessPromise=null}
 })();
 instagramDeveloperAccessPromise=request;
 return request;
}
function ensureInstagramDemoChildProgress(){
 let modal=$('instagramDemoChildProgress');if(modal)return modal;
 modal=document.createElement('div');modal.id='instagramDemoChildProgress';modal.className='instagram-demo-child-progress hidden';modal.innerHTML='<div class="instagram-demo-child-progress-card" role="dialog" aria-modal="true"><p class="instagram-demo-child-progress-kicker">Developer tool</p><h2>Generate demo child</h2><img class="instagram-demo-child-progress-photo hidden" alt=""><strong class="instagram-demo-child-progress-stage">Starting…</strong><p class="instagram-demo-child-progress-detail"></p><button class="secondary instagram-demo-child-progress-close hidden" type="button">Close</button></div>';
 document.body.appendChild(modal);const close=modal.querySelector('.instagram-demo-child-progress-close');close.onclick=()=>modal.classList.add('hidden');return modal;
}
function setInstagramDemoChildProgress(stage,detail='',photo=null,finished=false){
 const modal=ensureInstagramDemoChildProgress(),img=modal.querySelector('.instagram-demo-child-progress-photo'),close=modal.querySelector('.instagram-demo-child-progress-close');
 modal.querySelector('.instagram-demo-child-progress-stage').textContent=stage||'';modal.querySelector('.instagram-demo-child-progress-detail').textContent=detail||'';
 if(photo){img.src=photo;img.classList.remove('hidden')}else{img.removeAttribute('src');img.classList.add('hidden')}
 close.classList.toggle('hidden',!finished);modal.classList.remove('hidden');
}
async function generateInstagramDemoChild(){
 const button=$('instagramDemoChildButton');if(instagramDemoChildRunning)return;
 if(!currentUser){alert('Sign in to the developer account first.');return}
 const allowed=await checkInstagramDeveloperAccess({force:true});if(!allowed){alert('Developer access is required.');return}
 instagramDemoChildRunning=true;if(button){button.disabled=true;button.textContent='Generating demo child…'}
 let createdChildId=null;
 try{
  const access=await currentAccessToken();if(!access)throw new Error('Your Moonbeam session has expired. Please sign in again.');
  const requestedGender=String($('instagramDemoChildGender')?.value||'random');
  const requestedAge=String($('instagramDemoChildAge')?.value||'random');
  const chosenBits=[];if(requestedGender==='male')chosenBits.push('a boy');else if(requestedGender==='female')chosenBits.push('a girl');if(/^\d+$/.test(requestedAge))chosenBits.push(`age ${requestedAge}`);
  setInstagramDemoChildProgress('Inventing a fictional child…',chosenBits.length?`Moonbeam is inventing ${chosenBits.join(', ')}, choosing a name and appearance, then creating a portrait.`:'Moonbeam is choosing a name, age and appearance, then creating a portrait.');
  const profileResponse=await fetch('/api/resend-inbound?action=instagram-demo-child',{method:'POST',headers:{Authorization:`Bearer ${access}`,'Content-Type':'application/json'},body:JSON.stringify({existingNames:castMembers246.filter(m=>m.kind==='child').map(m=>m.name),gender:requestedGender,age:requestedAge})});
  const profileRaw=await profileResponse.text();let profileData={};try{profileData=JSON.parse(profileRaw)}catch{}
  if(!profileResponse.ok||!profileData?.ok||!profileData?.profile)throw new Error(profileData?.error||'Moonbeam could not invent the demo child.');
  const profile=profileData.profile;if(!/^data:image\/jpeg;base64,/i.test(profile.portraitDataUrl||''))throw new Error('The fictional child portrait was not returned correctly.');
  setInstagramDemoChildProgress(`Meet ${profile.name}, age ${profile.age}`,'Saving this fictional child and portrait to Your Cast…',profile.portraitDataUrl);

  const payload={parent_id:currentUser.id,kind:'child',name:profile.name,age:Number(profile.age),gender:profile.gender==='female'?'female':'male',relationship:'__moonbeam_demo__',animal_type:null,breed:null};
  const inserted=await supabaseClient.from('cast_members').insert(payload).select().single();if(inserted.error||!inserted.data?.id)throw new Error(inserted.error?.message||'Could not add the demo child to Your Cast.');
  createdChildId=inserted.data.id;
  await childPhotoPut(currentPhotoKey(createdChildId),profile.portraitDataUrl);
  const photoSaved=await uploadCloudChildPhoto(createdChildId,profile.portraitDataUrl);
  if(!photoSaved){await supabaseClient.from('cast_members').delete().eq('id',createdChildId);await childPhotoDelete(currentPhotoKey(createdChildId));createdChildId=null;throw new Error('The demo portrait could not be saved to the Cast profile.');}
  await loadCastMembers246();syncGenerationAdapter246();await renderCast246();
  setInstagramDemoChildProgress(`✓ ${profile.name} added to Your Cast`,'No story has been generated. Choose the child in Create Story whenever you are ready to make a story and post its Reel in the normal way.',profile.portraitDataUrl,true);
  return {ok:true,childId:createdChildId,childName:profile.name};
 }catch(error){
  console.error('Instagram demo child',error);setInstagramDemoChildProgress('Demo child stopped',error?.message||String(error),null,true);return {ok:false,error:error?.message||String(error)};
 }finally{
  instagramDemoChildRunning=false;if(button){button.disabled=false;button.textContent='Generate demo child'}
 }
}
$('instagramDemoChildButton')?.addEventListener('click',generateInstagramDemoChild);

